 */
import React from "react";

export function UserProfileCard8() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>User Profile Card</title>
    <!-- Tailwind CSS CDN -->
    <link href="https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css" rel="stylesheet">
    <style>
        /* Fade-in animation for the card */
        @keyframes fadeIn {
            from {
                opacity: 0;
                transform: translateY(20px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }
        .animate-fade-in {
            animation: fadeIn 0.8s ease-out forwards;
        }

        /* Gradient for fallback cover image if no URL is provided */
        .cover-gradient-fallback {
            background: linear-gradient(to right top, #a78bfa, #818cf8, #6366f1);
        }
    </style>
</head>
<body class="bg-gray-100 flex items-center justify-center min-h-screen p-4">

    <div class="relative w-full max-w-md bg-white shadow-xl rounded-lg overflow-hidden animate-fade-in">
        <!-- Cover Image Section -->
        <div class="h-40 bg-cover bg-center cover-gradient-fallback"
             style="background-image: url('https://images.unsplash.com/photo-1549880338-65ddcdfd017b?ixlib=rb-1.2.1&q=80&fm=jpg&crop=entropy&cs=tinysrgb&w=400&fit=max&ixid=eyJhcHBfaWQiOjE0NTg5fQ');">
            <!-- You can replace the URL with your desired cover image -->
        </div>

        <!-- Profile Picture and Details Section -->
        <div class="relative px-6 -mt-20">
            <!-- Profile Picture -->
            <img class="w-32 h-32 rounded-full border-4 border-white mx-auto shadow-md object-cover"
                 src="https://images.unsplash.com/photo-1549880338-65ddcdfd017b?ixlib=rb-1.2.1&q=80&fm=jpg&crop=entropy&cs=tinysrgb&w=400&fit=max&ixid=eyJhcHBfaWQiOjE0NTg5fQ"
                 alt="Profile Picture">
            <!-- You can replace the URL with your desired profile picture -->

            <!-- User Info -->
            <div class="text-center mt-4">
                <h2 class="text-2xl font-semibold text-gray-800">Jane Doe</h2>
                <p class="text-gray-600">Software Engineer | UI/UX Designer</p>
                <p class="text-sm text-gray-500 mt-2">Passionate about creating intuitive and beautiful web experiences.</p>
            </div>

            <!-- Optional: Social Links or Stats -->
            <div class="flex justify-center mt-6 space-x-4 border-t pt-6 border-gray-100">
                <div class="text-center">
                    <p class="font-bold text-lg text-gray-800">1.2K</p>
                    <p class="text-gray-500 text-sm">Followers</p>
                </div>
                <div class="text-center">
                    <p class="font-bold text-lg text-gray-800">250</p>
                    <p class="text-gray-500 text-sm">Following</p>
                </div>
                <div class="text-center">
                    <p class="font-bold text-lg text-gray-800">50</p>
                    <p class="text-gray-500 text-sm">Projects</p>
                </div>
            </div>

            <!-- Call to Action Button (Optional) -->
            <div class="mt-8 mb-4">
                <button class="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded-md transition duration-300">
                    Connect
                </button>
            </div>
        </div>
    </div>

</body>
</html>" }} />
  );
}
